source('/home/jinshengxi/bladder_metabolism/results/llps_C5_highlow_cellchat_ligand_v1/scripts/common.R')
db<-CellChatDB.human;d<-as.data.table(db$interaction,keep.rownames='feature');parts<-function(s){v<-if(s%in%rownames(db$complex))as.character(unlist(db$complex[s,,drop=FALSE]))else s;unique(v[!is.na(v)&nzchar(v)])}
d[,ligand_genes:=vapply(ligand,function(s)paste(parts(s),collapse=';'),character(1))];d[,receptor_genes:=vapply(receptor,function(s)paste(parts(s),collapse=';'),character(1))];writecsv(d[,.(feature,ligand,receptor,ligand_genes,receptor_genes,pathway_name,annotation)],file.path(OUT,'00_input_audit/DB_interaction_gene_components.csv'))
genes<-fread(file.path(OUT,'05_LLPS_ligand_correlation/gene_universe.csv'))$gene;maps<-rbindlist(lapply(seq_len(nrow(d)),function(i)data.table(gene=parts(d$ligand[i]),DB_ligand=d$ligand[i],feature=d$feature[i],pathway=d$pathway_name[i],category=d$annotation[i])));writecsv(maps[gene%in%genes],file.path(OUT,'00_input_audit/expressed_DB_ligand_gene_mapping.csv.gz'))
warn<-character();mat<-matrix(1,nrow=2,ncol=3,dimnames=list(c('FN1','MDK'),paste0('cell',1:3)));meta<-data.frame(group=factor(rep('C5',3)),row.names=colnames(mat));invisible(withCallingHandlers(createCellChat(mat,meta=meta,group.by='group'),warning=function(w){warn<<-c(warn,conditionMessage(w));invokeRestart('muffleWarning')}));writeLines(warn,file.path(OUT,'00_input_audit/constructor_warning_reproduction.txt'))
rs<-lapply(list.files(file.path(OUT,'02_CellChat_highlow'),pattern='unfiltered.rds',recursive=TRUE,full.names=TRUE),function(p){u<-readRDS(p);data.table(job_id=basename(dirname(p)),n_samples_in_native_meta=uniqueN(u$meta$samples),native_sample_label=paste(unique(u$meta$samples),collapse=';'))});r<-rbindlist(rs);stopifnot(all(r$n_samples_in_native_meta==1));writecsv(r,file.path(OUT,'00_input_audit/native_single_specimen_QC.csv'));cat('DATABASE COMPONENTS AND SINGLE-SPECIMEN AUDIT PASS\n')
